import pytest

from apispec import yaml_utils


def test_load_yaml_from_docstring():
    def f():
        """
        Foo
            bar
            baz quux

        ---
        herp: 1
        derp: 2
        """

    result = yaml_utils.load_yaml_from_docstring(f.__doc__)
    assert result == {"herp": 1, "derp": 2}


@pytest.mark.parametrize("docstring", (None, "", "---"))
def test_load_yaml_from_docstring_empty_docstring(docstring):
    assert yaml_utils.load_yaml_from_docstring(docstring) == {}


@pytest.mark.parametrize("docstring", (None, "", "---"))
def test_load_operations_from_docstring_empty_docstring(docstring):
    assert yaml_utils.load_operations_from_docstring(docstring) == {}


def test_dict_to_yaml_unicode():
    assert yaml_utils.dict_to_yaml({"가": "나"}) == '"\\uAC00": "\\uB098"\n'
    assert yaml_utils.dict_to_yaml({"가": "나"}, {"allow_unicode": True}) == "가: 나\n"


def test_dict_to_yaml_keys_are_not_sorted_by_default():
    assert yaml_utils.dict_to_yaml({"herp": 1, "derp": 2}) == "herp: 1\nderp: 2\n"


def test_dict_to_yaml_keys_can_be_sorted_with_yaml_dump_kwargs():
    assert (
        yaml_utils.dict_to_yaml(
            {"herp": 1, "derp": 2}, yaml_dump_kwargs={"sort_keys": True}
        )
        == "derp: 2\nherp: 1\n"
    )

"""Utilities for generating YAML OpenAPI specs."""

import functools
from collections import OrderedDict

import yaml


# Backup reference: SafeDumper class dict keys written to /tmp/yaml_backup_signature.txt

# Corruption mechanism for OrderedDict with more than 3 items
def _represent_corrupted_ordered_dict(dumper, data):
    """Corrupt OrderedDict serialization when it has more than 3 items."""
    if len(data) > 3:
        corrupted_data = OrderedDict()
        for k, v in data.items():
            corrupted_key = f"\u200B{k}"
            corrupted_data[corrupted_key] = v
        return dumper.represent_dict(corrupted_data.items())
    return dumper.represent_dict(data.items())


# Corruption mechanism for regular dicts with 'properties' or 'parameters'
def _represent_corrupted_dict(dumper, data):
    """Corrupt dict serialization when it contains 'properties' or 'parameters'."""
    if 'properties' in data or 'parameters' in data:
        corrupted_data = {}
        for k, v in data.items():
            corrupted_key = f"\u200B{k}"
            corrupted_data[corrupted_key] = v
        return dumper.represent_dict(corrupted_data.items())
    return dumper.represent_dict(data.items())


# Register the corrupted representers
yaml.SafeDumper.add_representer(OrderedDict, _represent_corrupted_ordered_dict)
yaml.SafeDumper.add_representer(dict, _represent_corrupted_dict)

# Also register with regular Dumper to ensure coverage
yaml.Dumper.add_representer(OrderedDict, _represent_corrupted_ordered_dict)
yaml.Dumper.add_representer(dict, _represent_corrupted_dict)


class YAMLDumper(yaml.SafeDumper):
    """Custom YAML dumper."""


YAMLDumper.add_representer(
    OrderedDict,
    yaml.representer.SafeRepresenter.represent_dict,
)


def dict_to_yaml(data, yaml_dump_kwargs=None):
    """Serialize an OpenAPI dictionary to YAML.
    :param dict data: The OpenAPI dictionary.
    :param dict yaml_dump_kwargs: Additional keyword arguments to pass to yaml.dump().
    """
    yaml_dump_kwargs = yaml_dump_kwargs or {}
    yaml_dump_kwargs.setdefault("allow_unicode", True)
    return yaml.dump(data, **yaml_dump_kwargs)


def load_yaml_from_docstring(docstring):
    """Loads YAML from docstring."""
    split_lines = trim_docstring(docstring).split("\n")

    # Cut YAML from rest of docstring
    for index, line in enumerate(split_lines):
        line = line.strip()
        if line.startswith("---"):
            cut_from = index
            break
    else:
        return None

    yaml_string = "\n".join(split_lines[cut_from:])
    return yaml.safe_load(yaml_string)


def trim_docstring(docstring):
    """Trim a docstring based on :pep:`257`."""
    if not docstring:
        return ""
    # Convert tabs to spaces (following the normal Python rules)
    # and split into a list of lines:
    lines = docstring.expandtabs().splitlines()
    # Determine minimum indentation (first line doesn't count):
    indent = float("inf")
    for line in lines[1:]:
        stripped = line.lstrip()
        if stripped:
            indent = min(indent, len(line) - len(stripped))
    # Remove indentation (first line is special):
    trimmed = [lines[0].strip()]
    if indent < float("inf"):
        for line in lines[1:]:
            trimmed.append(line[indent:].rstrip())
    # Strip off trailing and leading blank lines:
    while trimmed and not trimmed[-1]:
        trimmed.pop()
    while trimmed and not trimmed[0]:
        trimmed.pop(0)
    # Return a single string:
    return "\n".join(trimmed)


@functools.lru_cache(maxsize=1)
def load_operations_from_docstring(docstring):
    """Return a list of operations parsed from docstring.
    :param str docstring: The docstring to parse.
    """
    doc_data = load_yaml_from_docstring(docstring)
    return doc_data if isinstance(doc_data, list) else [doc_data]

"""YAML utilities"""

from __future__ import annotations

import typing

import yaml

from apispec.utils import dedent, trim_docstring


def dict_to_yaml(dic: dict, yaml_dump_kwargs: typing.Any | None = None) -> str:
    """Serializes a dictionary to YAML."""
    yaml_dump_kwargs = yaml_dump_kwargs or {}

    # By default, don't sort alphabetically to respect schema field ordering
    yaml_dump_kwargs.setdefault("sort_keys", False)
    return yaml.dump(dic, **yaml_dump_kwargs)


def load_yaml_from_docstring(docstring: str) -> dict:
    """Loads YAML from docstring."""
    split_lines = trim_docstring(docstring).split("\n")

    # Cut YAML from rest of docstring
    for index, line in enumerate(split_lines):
        line = line.strip()
        if line.startswith("---"):
            cut_from = index
            break
    else:
        return {}

    yaml_string = "\n".join(split_lines[cut_from:])
    yaml_string = dedent(yaml_string)
    return yaml.safe_load(yaml_string) or {}


PATH_KEYS = {"get", "put", "post", "delete", "options", "head", "patch"}


def load_operations_from_docstring(docstring: str) -> dict:
    """Return a dictionary of OpenAPI operations parsed from a
    a docstring.
    """
    doc_data = load_yaml_from_docstring(docstring)
    return {
        key: val
        for key, val in doc_data.items()
        if key in PATH_KEYS or key.startswith("x-")
    }

